CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE EXTENSION IF NOT EXISTS vector;
CREATE TYPE user_role AS ENUM ('MEMBER','TRAINER','ADMIN');
CREATE TYPE booking_status AS ENUM ('PENDING','CONFIRMED','CANCELLED','REJECTED','COMPLETED');
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, full_name TEXT NOT NULL, role user_role NOT NULL DEFAULT 'MEMBER', is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE member_profiles (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, phone TEXT, date_of_birth DATE, fitness_level TEXT CHECK (fitness_level IN ('BEGINNER','INTERMEDIATE','ADVANCED')), created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE trainer_profiles (user_id UUID PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, headline TEXT NOT NULL DEFAULT '', biography TEXT NOT NULL DEFAULT '', hourly_rate NUMERIC(8,2) NOT NULL CHECK(hourly_rate >= 0), years_experience SMALLINT NOT NULL DEFAULT 0 CHECK(years_experience >= 0), rating NUMERIC(2,1) NOT NULL DEFAULT 5 CHECK(rating BETWEEN 0 AND 5), embedding VECTOR(128), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE trainer_specializations (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, trainer_id UUID NOT NULL REFERENCES trainer_profiles(user_id) ON DELETE CASCADE, name TEXT NOT NULL, UNIQUE(trainer_id,name));
CREATE TABLE trainer_availability (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), trainer_id UUID NOT NULL REFERENCES trainer_profiles(user_id) ON DELETE CASCADE, starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, is_open BOOLEAN NOT NULL DEFAULT TRUE, CHECK(ends_at > starts_at), UNIQUE(trainer_id,starts_at));
CREATE TABLE bookings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), member_id UUID NOT NULL REFERENCES member_profiles(user_id), trainer_id UUID NOT NULL REFERENCES trainer_profiles(user_id), starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ NOT NULL, status booking_status NOT NULL DEFAULT 'PENDING', notes TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), updated_at TIMESTAMPTZ NOT NULL DEFAULT now(), CHECK(ends_at > starts_at), CONSTRAINT trainer_no_confirmed_overlap EXCLUDE USING gist (trainer_id WITH =, tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE (status='CONFIRMED'));
CREATE TABLE booking_audit (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, booking_id UUID NOT NULL, actor_id UUID REFERENCES users(id) ON DELETE SET NULL, action TEXT NOT NULL, old_status booking_status, new_status booking_status, changed_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE fitness_goals (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), member_id UUID NOT NULL REFERENCES member_profiles(user_id) ON DELETE CASCADE, description TEXT NOT NULL, embedding VECTOR(128), target_date DATE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE exercise_embeddings (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name TEXT NOT NULL UNIQUE, description TEXT NOT NULL, category TEXT NOT NULL, embedding VECTOR(128) NOT NULL, metadata JSONB NOT NULL DEFAULT '{}', created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX bookings_member_start_idx ON bookings(member_id,starts_at DESC);
CREATE INDEX bookings_trainer_start_idx ON bookings(trainer_id,starts_at DESC);
CREATE INDEX availability_lookup_idx ON trainer_availability(trainer_id,starts_at) WHERE is_open;
CREATE INDEX trainer_specialization_name_idx ON trainer_specializations(name);
CREATE INDEX trainer_embedding_cosine_idx ON trainer_profiles USING hnsw (embedding vector_cosine_ops) WHERE embedding IS NOT NULL;
CREATE INDEX exercise_embedding_cosine_idx ON exercise_embeddings USING hnsw (embedding vector_cosine_ops);
CREATE INDEX goal_embedding_cosine_idx ON fitness_goals USING hnsw (embedding vector_cosine_ops) WHERE embedding IS NOT NULL;
CREATE OR REPLACE FUNCTION audit_booking_change() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='INSERT' THEN INSERT INTO booking_audit(booking_id,action,new_status) VALUES(NEW.id,'CREATED',NEW.status); ELSIF NEW.status IS DISTINCT FROM OLD.status THEN INSERT INTO booking_audit(booking_id,action,old_status,new_status) VALUES(NEW.id,'STATUS_CHANGED',OLD.status,NEW.status); END IF; NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER bookings_audit_trigger BEFORE INSERT OR UPDATE ON bookings FOR EACH ROW EXECUTE FUNCTION audit_booking_change();
CREATE OR REPLACE FUNCTION create_booking(p_member UUID,p_trainer UUID,p_start TIMESTAMPTZ,p_end TIMESTAMPTZ,p_notes TEXT DEFAULT NULL) RETURNS UUID LANGUAGE plpgsql AS $$ DECLARE result UUID; BEGIN IF NOT EXISTS(SELECT 1 FROM trainer_availability WHERE trainer_id=p_trainer AND is_open AND starts_at<=p_start AND ends_at>=p_end FOR UPDATE) THEN RAISE EXCEPTION 'Requested time is not available'; END IF; INSERT INTO bookings(member_id,trainer_id,starts_at,ends_at,status,notes) VALUES(p_member,p_trainer,p_start,p_end,'CONFIRMED',p_notes) RETURNING id INTO result; RETURN result; END $$;
CREATE VIEW trainer_booking_summary AS SELECT t.user_id trainer_id,u.full_name,COUNT(b.id) FILTER(WHERE b.status='CONFIRMED') confirmed_bookings,COUNT(b.id) total_bookings FROM trainer_profiles t JOIN users u ON u.id=t.user_id LEFT JOIN bookings b ON b.trainer_id=t.user_id GROUP BY t.user_id,u.full_name;
CREATE OR REPLACE FUNCTION recommend_trainers(query_embedding VECTOR(128), result_limit INT DEFAULT 10) RETURNS TABLE(trainer_id UUID,full_name TEXT,similarity REAL) LANGUAGE SQL STABLE AS $$ SELECT tp.user_id,u.full_name,(1-(tp.embedding <=> query_embedding))::REAL FROM trainer_profiles tp JOIN users u ON u.id=tp.user_id WHERE tp.embedding IS NOT NULL ORDER BY tp.embedding <=> query_embedding LIMIT result_limit $$;
